using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace ApiMcpServer;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private const string BaseUrl = "https://jsonplaceholder.typicode.com";

    [McpServerTool, Description("Fetch a user by their numeric ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetStringAsync(
            $"{BaseUrl}/users/{userId}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID. Omit to list all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"{BaseUrl}/posts?userId={userId.Value}"
            : $"{BaseUrl}/posts";

        logger.LogInformation("Listing posts from {Url}", url);
        var response = await httpClient.GetStringAsync(url, cancellationToken);
        return response;
    }

    [McpServerTool, Description("Create a new post via the REST API.")]
    public async Task<string> CreatePost(
        [Description("The user ID authoring the post")] int userId,
        [Description("The title of the post")] string title,
        [Description("The body content of the post")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var payload = JsonSerializer.Serialize(new { userId, title, body });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync($"{BaseUrl}/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

